BEGIN TRANSACTION;
  UPDATE accounts SET balance = balance - 500 WHERE account_id = 1;
  UPDATE accounts SET balance = balance + 500 WHERE account_id = 2;
COMMIT;  -- Both succeed together

-- If any statement fails:
ROLLBACK;  -- Neither change is applied

SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;
BEGIN;
  SELECT balance FROM accounts WHERE id = 1;  -- locks row
  UPDATE accounts SET balance = balance - 100 WHERE id = 1;
COMMIT;

-- PostgreSQL with error handling
DO $$
BEGIN
  BEGIN  -- inner block for error handling
    UPDATE accounts
    SET balance = balance - 500
    WHERE account_id = 1 AND balance >= 500;  -- check funds

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Insufficient funds in account 1';
    END IF;

    UPDATE accounts
    SET balance = balance + 500
    WHERE account_id = 2;

    COMMIT;
    RAISE NOTICE 'Transfer successful';
  EXCEPTION
    WHEN OTHERS THEN
      ROLLBACK;
      RAISE;
  END;
END;
$$;

-- Deadlock example:
-- TX1: locks row A, waits for row B
-- TX2: locks row B, waits for row A → deadlock!

-- Prevention strategies:
-- 1. Always lock tables in the same order
-- 2. Keep transactions short
-- 3. Use lower isolation levels where safe
-- 4. Use SELECT ... FOR UPDATE to acquire locks upfront
BEGIN;
  SELECT * FROM accounts WHERE id IN (1, 2) ORDER BY id FOR UPDATE;
  -- Locks both rows in consistent order
  UPDATE accounts SET balance = balance - 100 WHERE id = 1;
  UPDATE accounts SET balance = balance + 100 WHERE id = 2;
COMMIT;

BEGIN;
  INSERT INTO orders VALUES (1, 100, '2024-01-01');
  SAVEPOINT after_order;  -- checkpoint

  INSERT INTO order_items VALUES (1, 'Product A', 2);
  -- Something goes wrong with the item...
  ROLLBACK TO SAVEPOINT after_order;  -- undo only order_items insert
  -- The order insert is still in effect!

  -- Try a different item
  INSERT INTO order_items VALUES (1, 'Product B', 1);
COMMIT;

-- PostgreSQL stored procedure
CREATE OR REPLACE PROCEDURE add_employee(
  p_name       VARCHAR,
  p_email      VARCHAR,
  p_department VARCHAR,
  p_salary     DECIMAL
)
LANGUAGE plpgsql AS $$
BEGIN
  -- Validation
  IF p_salary <= 0 THEN
    RAISE EXCEPTION 'Salary must be positive, got %', p_salary;
  END IF;

  IF EXISTS (SELECT 1 FROM employees WHERE email = p_email) THEN
    RAISE EXCEPTION 'Email % already exists', p_email;
  END IF;

  INSERT INTO employees (name, email, department, salary, hire_date)
  VALUES (p_name, p_email, p_department, p_salary, CURRENT_DATE);

  COMMIT;
  RAISE NOTICE 'Employee % added successfully', p_name;
EXCEPTION
  WHEN OTHERS THEN
    ROLLBACK;
    RAISE;
END;
$$;

-- Call it:
CALL add_employee('John Smith', 'john@co.com', 'Engineering', 120000);

-- Create audit log table
CREATE TABLE employee_audit (
  audit_id    SERIAL PRIMARY KEY,
  employee_id INT,
  action      VARCHAR(10),
  old_salary  DECIMAL,
  new_salary  DECIMAL,
  changed_by  VARCHAR(100),
  changed_at  TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Trigger function
CREATE OR REPLACE FUNCTION log_salary_change()
RETURNS TRIGGER AS $$
BEGIN
  IF OLD.salary != NEW.salary THEN
    INSERT INTO employee_audit (employee_id, action, old_salary, new_salary, changed_by)
    VALUES (NEW.employee_id, 'UPDATE', OLD.salary, NEW.salary, CURRENT_USER);
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Attach trigger
CREATE TRIGGER salary_audit_trigger
AFTER UPDATE ON employees
FOR EACH ROW
EXECUTE FUNCTION log_salary_change();

-- PostgreSQL
CREATE OR REPLACE FUNCTION business_days(start_dt DATE, end_dt DATE)
RETURNS INTEGER AS $$
DECLARE
  total_days INTEGER := 0;
  current_dt DATE := start_dt;
BEGIN
  WHILE current_dt <= end_dt LOOP
    IF EXTRACT(DOW FROM current_dt) NOT IN (0, 6) THEN  -- 0=Sun, 6=Sat
      total_days := total_days + 1;
    END IF;
    current_dt := current_dt + 1;
  END LOOP;
  RETURN total_days;
END;
$$ LANGUAGE plpgsql;

-- Usage
SELECT business_days('2024-01-01', '2024-01-31') AS working_days;

