SELECT * FROM customers
WHERE phone IS NULL OR TRIM(phone) = '';

-- NULLIF trick to treat empty string as NULL
SELECT * FROM customers
WHERE NULLIF(TRIM(phone), '') IS NULL;

-- PostgreSQL
SELECT id, UNNEST(string_to_array(tags, ',')) AS tag FROM articles;

-- BigQuery
SELECT id, tag FROM articles, UNNEST(SPLIT(tags, ',')) AS tag;

-- SQL Server 2016+
SELECT a.id, s.value AS tag FROM articles a
CROSS APPLY STRING_SPLIT(a.tags, ',') s;

-- Snowflake
SELECT a.id, s.value AS tag FROM articles a,
TABLE(FLATTEN(SPLIT(a.tags, ','))) s;

-- PostgreSQL: SPLIT_PART
SELECT email, SPLIT_PART(email, '@', 2) AS domain FROM users;

-- MySQL
SELECT email, SUBSTRING_INDEX(email, '@', -1) AS domain FROM users;

-- BigQuery
SELECT email, REGEXP_EXTRACT(email, '@(.+)') AS domain FROM users;

-- Count users by domain
SELECT SPLIT_PART(email, '@', 2) AS domain, COUNT(*) AS users
FROM users GROUP BY 1 ORDER BY users DESC;

-- PostgreSQL
SELECT customer_id, date_of_birth,
  DATE_PART('year', AGE(date_of_birth))::INT AS age FROM customers;

-- BigQuery
SELECT customer_id,
  DATE_DIFF(CURRENT_DATE(), date_of_birth, YEAR) AS age FROM customers;

-- SQL Server
SELECT customer_id,
  DATEDIFF(YEAR, date_of_birth, GETDATE()) AS age FROM customers;

-- Surrogate key (preferred)
CREATE TABLE customers (
  customer_key SERIAL PRIMARY KEY,   -- surrogate
  customer_id  VARCHAR UNIQUE,       -- natural key as constraint
  name         VARCHAR
);

-- Most common value using RANK()
SELECT department
FROM (
  SELECT department, COUNT(*) AS cnt,
    RANK() OVER (ORDER BY COUNT(*) DESC) AS rnk
  FROM employees GROUP BY department
) t WHERE rnk = 1;

-- PostgreSQL built-in
SELECT MODE() WITHIN GROUP (ORDER BY department) FROM employees;

-- Keep one record per duplicate group (PostgreSQL)
DELETE FROM orders
WHERE ctid NOT IN (
  SELECT MIN(ctid) FROM orders
  GROUP BY order_id, customer_id, order_date
);

-- Universal approach using ROW_NUMBER
WITH ranked AS (
  SELECT ctid, ROW_NUMBER() OVER (PARTITION BY order_id ORDER BY created_at DESC) AS rn
  FROM orders
)
DELETE FROM orders WHERE ctid IN (SELECT ctid FROM ranked WHERE rn > 1);

WITH first_seen AS (
  SELECT user_id, MIN(event_date) AS first_date FROM events GROUP BY user_id
),
daily AS (
  SELECT first_date AS dt, COUNT(*) AS new_users FROM first_seen GROUP BY 1
)
SELECT dt, new_users,
  SUM(new_users) OVER (ORDER BY dt) AS cumulative_users
FROM daily ORDER BY dt;

-- Explicit CAST to align data types
SELECT a.*, b.*
FROM table_a a
JOIN table_b b ON CAST(a.id AS VARCHAR) = b.id;

-- NULL-safe cast in BigQuery
JOIN table_b b ON a.id = SAFE_CAST(b.id AS INT64);

-- Snowflake
JOIN table_b b ON a.id = TRY_CAST(b.id AS INT);

-- PostgreSQL: dynamic pivot using JSON
SELECT student_id,
  jsonb_object_agg(subject, score ORDER BY subject) AS scores_json
FROM student_scores
GROUP BY student_id;

-- Output: {"English": 88, "Math": 95, "Science": 91}

-- Access a specific subject from JSON
SELECT student_id, (scores_json->>'Math')::INT AS math_score
FROM (
  SELECT student_id, jsonb_object_agg(subject, score) AS scores_json
  FROM student_scores GROUP BY student_id
) t;

WITH monthly AS (
  SELECT DATE_TRUNC('month', order_date) AS mo, SUM(total_amount) AS rev FROM orders GROUP BY 1
),
changes AS (
  SELECT mo, rev, rev - LAG(rev) OVER (ORDER BY mo) AS mom_delta FROM monthly
)
SELECT mo, rev, mom_delta FROM changes
WHERE mom_delta = (SELECT MAX(mom_delta) FROM changes);

SELECT customer_id, order_id, order_date,
  ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY order_date) AS customer_order_number
FROM orders ORDER BY customer_id, order_date;

SELECT customer_id, total_spend FROM (
  SELECT customer_id,
    SUM(total_amount) AS total_spend,
    CUME_DIST() OVER (ORDER BY SUM(total_amount) DESC) AS cd
  FROM orders GROUP BY customer_id
) t WHERE cd <= 0.20 ORDER BY total_spend DESC;

SELECT user_id, event_type, event_time,
  LEAD(event_time) OVER (PARTITION BY user_id ORDER BY event_time) AS next_event,
  EXTRACT(EPOCH FROM (
    LEAD(event_time) OVER (PARTITION BY user_id ORDER BY event_time) - event_time
  ))/60.0 AS minutes_to_next
FROM user_events ORDER BY user_id, event_time;

