WITH all_dates AS (
  SELECT generate_series::DATE AS dt
  FROM generate_series((SELECT MIN(metric_date) FROM daily_metrics), CURRENT_DATE-1, '1 day'::INTERVAL)
),
missing AS (
  SELECT ad.dt FROM all_dates ad LEFT JOIN daily_metrics dm ON ad.dt=dm.metric_date WHERE dm.metric_date IS NULL
)
INSERT INTO daily_metrics (metric_date, metric_value, is_backfilled)
SELECT dt, 0, TRUE FROM missing;

