CREATE OR REPLACE FUNCTION capture_audit() RETURNS TRIGGER AS $$
BEGIN
  IF TG_OP='UPDATE' THEN
    IF OLD.salary IS DISTINCT FROM NEW.salary THEN
      INSERT INTO audit_trail (table_name,record_id,column_name,old_value,new_value,changed_by)
      VALUES (TG_TABLE_NAME, NEW.employee_id::TEXT, 'salary', OLD.salary::TEXT, NEW.salary::TEXT, CURRENT_USER);
    END IF;
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER emp_audit AFTER UPDATE ON employees
FOR EACH ROW EXECUTE FUNCTION capture_audit();

